const pptxgen = require("pptxgenjs");
const path = require("path");

// Slide 019 - sigmoid / tanh / tan / tan^-1 function graphs.
// House chrome (red frame, badge, title) follows the house frame rule.
// Panel palette and geometry are PIL-matched to unique_slides/slide_019.jpg.
// Plot interiors, axes, ticks, asymptotes and in-panel titles are generated by
// gen_slide_019_graphs_v3.py (measured data rects; v2 drew the axes on the
// panel border and clipped the y-tick labels outside the canvas).
const NUM = 19;
const TITLE = "Sigmoid, tanh, tan, and tan\u207B\u00B9 Function Graphs";
const FONT = "Arial";
const BG = "E8E8E8", RED = "C00000", YELLOW = "FFF9C4";
const PEACH = "FCE4D6", PEACH_BORDER = "E6B8A2";
const GRAY = "D9D9D9", GRAY_BORDER = "A6A6A6", PANEL_BG = "FEFFFD";

const W = 13.33, H = 7.5;
const PANEL_W = 305 / 72, PANEL_H = 178 / 72;
const IX = 0.15, IW = 13.03, IY = 0.15, IH = 7.2;
const DIR = "/home/codespace/ai_llm_slides/videos/machine-learning/09_introduction_to_neural_networks/recreated_pptx/build";
const GRAPH_DIR = DIR + "/graphs_slide_019";

// Equation art is rendered at 600 dpi by gen_slide_019_eqs_v3.py; its size is
// read from the manifest so the PNG is never rescaled.
const EQ_MANIFEST = require(path.join(DIR, "eq_019_manifest.json"));

// Caption boxes measured in the original (960x540, 1px = 1pt):
//   sigmoid peach 138..375 x 240..294   tanh peach 528..745 x 240..294
//   tan grey      165..305 x 468..498   arctan peach 545..687 x 467..497
const CAPS = {
  sigmoid: { w: 237 / 72, h: 0.60, dx: 0.0, gap: 0.04, fill: PEACH, line: PEACH_BORDER },
  tanh:    { w: 217 / 72, h: 0.60, dx: -8 / 72, gap: 0.04, fill: PEACH, line: PEACH_BORDER },
  tan:     { w: 140 / 72, h: 0.42, dx: -22.5 / 72, gap: 0.04, fill: GRAY, line: GRAY_BORDER },
  arctan:  { w: 142 / 72, h: 0.42, dx: -28.5 / 72, gap: 0.04, fill: PEACH, line: PEACH_BORDER },
};

const PANELS = [
  { key: "sigmoid", x: IX + 0.11 * IW, y: IY + 0.11 * IH },
  { key: "tanh", x: IX + 0.52 * IW, y: IY + 0.11 * IH },
  { key: "tan", x: IX + 0.11 * IW, y: IY + 0.55 * IH },
  { key: "arctan", x: IX + 0.52 * IW, y: IY + 0.55 * IH },
];

// Connector arrow: original ink x 426..478, y 373..394 (960px-space, 1px = 1pt)
// -> 0.722 x 0.292 in, centred in the gutter between the two bottom panels.
const GAP_LEFT = IX + 0.11 * IW + PANEL_W;
const GAP_RIGHT = IX + 0.52 * IW;
const GAP_CX = (GAP_LEFT + GAP_RIGHT) / 2;
const ARROW = {
  x: GAP_CX - 26 / 72, y: 373 / 72, w: 52 / 72, h: 21 / 72,
};

const pres = new pptxgen();
pres.layout = "LAYOUT_WIDE";
const s = pres.addSlide();
s.background = { color: BG };

// House chrome: outer frame, slide-number badge, title box.
s.addShape(pres.shapes.RECTANGLE, {
  x: 0.15, y: 0.15, w: W - 0.3, h: H - 0.3,
  fill: { type: "none" }, line: { color: RED, width: 1.5 },
});
s.addShape(pres.shapes.OVAL, {
  x: 12.48, y: 0.30, w: 0.5, h: 0.5,
  fill: { color: YELLOW }, line: { color: YELLOW, width: 0.5 },
});
s.addText(String(NUM), {
  x: 12.48, y: 0.30, w: 0.5, h: 0.5, align: "center", valign: "middle",
  fontSize: 18, bold: true, color: "333333", fontFace: FONT, margin: 0,
});
s.addText(TITLE, {
  x: 0.6, y: 0.28, w: 12.13, h: 0.55, align: "center", valign: "top",
  fontSize: 20, bold: true, color: RED, fontFace: FONT, margin: 0,
});

for (const p of PANELS) {
  const cap = CAPS[p.key];
  // Panel backdrop; the embedded plot image carries the measured blue-purple border.
  s.addShape(pres.shapes.RECTANGLE, {
    x: p.x, y: p.y, w: PANEL_W, h: PANEL_H,
    fill: { color: PANEL_BG }, line: { color: PANEL_BG, width: 0.25 },
  });
  s.addImage({
    path: GRAPH_DIR + "/graph_" + p.key + ".png",
    x: p.x, y: p.y, w: PANEL_W, h: PANEL_H,
  });

  const capX = p.x + (PANEL_W - cap.w) / 2 + cap.dx;
  const capY = p.y + PANEL_H + cap.gap;
  s.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: capX, y: capY, w: cap.w, h: cap.h,
    fill: { color: cap.fill }, line: { color: cap.line, width: 1 },
  });
  const info = EQ_MANIFEST["eq_" + p.key][0];
  s.addImage({
    path: DIR + "/eq_" + p.key + ".png",
    x: capX + (cap.w - info.w_in) / 2,
    y: capY + (cap.h - info.h_in) / 2,
    w: info.w_in, h: info.h_in,
  });
}

// Hollow red arrow pointing from the tan graph to the arctan graph.
s.addShape(pres.shapes.RIGHT_ARROW, {
  x: ARROW.x, y: ARROW.y, w: ARROW.w, h: ARROW.h,
  fill: { color: "FFFFFF" }, line: { color: RED, width: 2 },
});

pres.writeFile({ fileName: DIR + "/slide_019_recreated.pptx" })
  .then(() => console.log("wrote " + DIR + "/slide_019_recreated.pptx"));
